<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import MobileShell from '@/components/MobileShell.vue'
import PrayerContent from '@/components/PrayerContent.vue'
import AtlasImage from './AtlasImage.vue'
import { apiBaseUrl } from '@/config/api'
import { createStudyPackageApi, type StudyPackage } from '@/api/studyPackages'
import { installedStudyPackages, installStudyPackage, removeStudyPackage, type InstalledStudyPackage } from '@/services/studyPackages'
import { studyPackageRows, studyPackageArticle } from '@/services/studyPackageLookup'
import { studyPackagesMessages } from '@/i18n/studyPackages'
import { useI18n } from '@/i18n'
import TemporaryPassage from './TemporaryPassage.vue'
import { resolveStudyReference } from '@/services/studyReference'
import { createChapterService } from '@/services/chapterService'
import { createIndexedDbChapterRepository } from '@/offline/indexedDbChapterRepository'
import { bibleApi } from '@/api'
import type { ReferenceGroup } from '@/services/verseStudy'
import SourceCard from './SourceCard.vue'
import CommentaryAnnotations from './CommentaryAnnotations.vue'
import {isCommentaryAnnotations} from '@/api/commentaryAnnotations'
const route=useRoute(),router=useRouter(),{language}=useI18n(),text=computed(()=>studyPackagesMessages[language.value])
const catalog=ref<StudyPackage[]>([]),installed=ref<InstalledStudyPackage[]>([]),unavailable=ref(false),failed=ref(false),loading=ref(''),progress=ref(0),query=ref(''),submitted=ref(''),offset=ref(0),rows=ref<Record<string,unknown>[]>([]),total=ref(0),article=ref<Awaited<ReturnType<typeof studyPackageArticle>>>(),images=ref<{id:string;url:string}[]>([])
const code=computed(()=>String(route.query.module??'')),entry=computed(()=>String(route.query.entry??'')),book=computed(()=>String(route.query.book??'')),current=computed(()=>installed.value.find(p=>p.manifest.id===code.value));let controller:AbortController|undefined
const temporary=ref<ReferenceGroup>(),temporaryCode=ref(''),chapterService=createChapterService(bibleApi,createIndexedDbChapterRepository())
const lexicons=ref<Record<string,unknown>[]>([]),selectedLexicon=computed(()=>String(route.query.lexicon??''))
const chosen=ref<string[]>([]),bundleName=ref(''),bundles=ref<{name:string;codes:string[]}[]>([]),queueing=ref(false),chosenBytes=computed(()=>catalog.value.filter(p=>chosen.value.includes(p.id)).reduce((sum,p)=>sum+p.bytes,0));let queueCancelled=false
try{const saved:unknown=JSON.parse(localStorage.getItem('bible-desktop:study-bundles')??'[]');if(Array.isArray(saved))bundles.value=saved.filter((b):b is {name:string;codes:string[]}=>typeof b?.name==='string'&&Array.isArray(b.codes)&&b.codes.every((code:unknown)=>typeof code==='string'))}catch{}
function saveBundle(){const name=bundleName.value.trim();if(!name||!chosen.value.length)return;bundles.value=[...bundles.value.filter(b=>b.name!==name),{name,codes:[...chosen.value]}];localStorage.setItem('bible-desktop:study-bundles',JSON.stringify(bundles.value));bundleName.value=''}
function cancel(){queueCancelled=true;controller?.abort()}
async function downloadChosen(){queueing.value=true;queueCancelled=false;try{for(const pack of catalog.value.filter(p=>chosen.value.includes(p.id))){if(queueCancelled)break;if(installed.value.some(p=>p.manifest.id===pack.id&&p.manifest.version===pack.version))continue;await download(pack);if(failed.value)break}}finally{queueing.value=false}}
async function reference(value:Record<string,unknown>){try{const resolved=await resolveStudyReference({book_slug:String(value.book_slug),chapter_number:typeof value.chapter==='number'?value.chapter:null,verse_from:typeof value.verse_from==='number'?value.verse_from:null,verse_to:typeof value.verse_to==='number'?value.verse_to:null},chapterService,String(current.value?.metadata.name??code.value),typeof value.book_osis==='string'?value.book_osis:undefined);temporaryCode.value=resolved.code;temporary.value=resolved.group}catch{failed.value=true}}
async function refresh(){installed.value=await installedStudyPackages();try{catalog.value=(await createStudyPackageApi({baseUrl:apiBaseUrl}).manifest()).packages;unavailable.value=!catalog.value.length}catch{unavailable.value=true}}
void refresh()
async function download(pack:StudyPackage){controller=new AbortController();loading.value=pack.id;progress.value=0;failed.value=false;try{await installStudyPackage(pack,apiBaseUrl,controller.signal,(bytes,total)=>progress.value=bytes/total);await refresh()}catch(error){if(!controller.signal.aborted)failed.value=true}finally{loading.value=''}}
async function remove(id:string){await removeStudyPackage(id);await refresh()}
watch([current,entry,book,submitted,offset,selectedLexicon],async(_,__,cleanup)=>{let stale=false;cleanup(()=>{stale=true});rows.value=[];article.value=undefined;total.value=0;for(const image of images.value)URL.revokeObjectURL(image.url);images.value=[];if(!current.value)return;try{const pack=current.value;lexicons.value=pack.manifest.kind==='strong'?(await studyPackageRows(pack,'lexicons.jsonl',{limit:Number.MAX_SAFE_INTEGER})).rows:[];if(entry.value){const body=await studyPackageArticle(pack,entry.value,selectedLexicon.value||undefined);if(stale)return;article.value=body;images.value=body?.media.map(m=>({id:m.id,url:URL.createObjectURL(m.file)}))??[]}else{const table=pack.manifest.kind==='commentary'&&!book.value?'books.jsonl':pack.manifest.kind==='cross_references'?'references.jsonl':pack.manifest.kind==='dictionary'&&pack.metadata.entries_count===0?'word_forms.jsonl':'entries.jsonl';const page=await studyPackageRows(pack,table,{query:submitted.value,entry:book.value||undefined,offset:offset.value,limit:30});if(!stale){rows.value=page.rows;total.value=page.total}}}catch{if(!stale)failed.value=true}},{immediate:true})
onBeforeUnmount(()=>{controller?.abort();for(const image of images.value)URL.revokeObjectURL(image.url)})
</script>
<template><MobileShell :back-to="entry ? `/study-downloads?module=${encodeURIComponent(code)}${book?`&book=${encodeURIComponent(book)}`:''}` : code ? '/study-downloads' : '/more'"><h1>{{ text.title }}</h1><p v-if="unavailable">{{ text.unavailable }}</p><p v-if="failed" role="alert">{{ text.error }}</p><p>{{ text.integrity }}</p><template v-if="!code"><fieldset><legend>{{ text.choose }}</legend><p>{{ text.total }}: {{ (chosenBytes/1024/1024).toFixed(1) }} MB</p><button :disabled="!chosen.length || !!loading || queueing" @click="downloadChosen">{{ text.downloadSelection }}</button><button v-if="queueing" @click="cancel">{{ text.cancel }}</button><label>{{ text.bundleName }}<input v-model="bundleName" maxlength="80"></label><button :disabled="!chosen.length || !bundleName.trim()" @click="saveBundle">{{ text.saveBundle }}</button><details v-if="bundles.length"><summary>{{ text.bundles }}</summary><button v-for="bundle in bundles" :key="bundle.name" @click="chosen=bundle.codes.filter(code=>catalog.some(p=>p.id===code))">{{ bundle.name }}</button></details></fieldset><article v-for="pack in catalog" :key="pack.id" class="pack"><label><input v-model="chosen" type="checkbox" :value="pack.id" :disabled="queueing">{{ text.choose }}</label><strong>{{ installed.find(p=>p.manifest.id===pack.id)?.metadata.name || pack.id }}</strong><small>{{ pack.kind }} · {{ (pack.bytes/1024/1024).toFixed(1) }} MB</small><button :disabled="!!loading || queueing || installed.some(p=>p.manifest.id===pack.id&&p.manifest.version===pack.version)" @click="download(pack)">{{ installed.some(p=>p.manifest.id===pack.id&&p.manifest.version===pack.version) ? text.installed : installed.some(p=>p.manifest.id===pack.id) ? text.update : text.download }}</button><template v-if="loading===pack.id"><progress :value="progress" max="1"/><button @click="cancel">{{ text.cancel }}</button></template></article><article v-for="pack in installed" :key="pack.manifest.id" class="pack"><strong>{{ pack.metadata.name || pack.manifest.id }}</strong><RouterLink :to="{query:{module:pack.manifest.id}}">{{ text.read }}</RouterLink><button @click="remove(pack.manifest.id)">{{ text.remove }}</button></article></template><template v-else-if="current"><h2>{{ current.metadata.name || code }}</h2><SourceCard :metadata="current.metadata" :version="current.manifest.version"/><template v-if="article"><select v-if="lexicons.length" :value="selectedLexicon||article.article.lexicon_code" :aria-label="text.choose" @change="router.replace({query:{...route.query,lexicon:($event.target as HTMLSelectElement).value}})"><option v-for="lexicon in lexicons" :key="String(lexicon.code)" :value="String(lexicon.code)">{{ lexicon.name }} · {{ lexicon.language }}</option></select><h3>{{ article.article.topic || article.article.title || article.article.word || article.article.id }}</h3><PrayerContent :content="String(article.article.body ?? article.article.content ?? '')"/><CommentaryAnnotations v-if="current.manifest.kind==='commentary'" :annotations="isCommentaryAnnotations(article.article.annotations)?article.article.annotations:null" :module-code="code" :source="String(current.metadata.name??code)"/><AtlasImage v-for="image in images" :key="image.id" :url="image.url" installed :title="String(article.article.topic??'')"/><RouterLink v-for="(link,index) in article.links" :key="index" :to="{query:{...route.query,entry:String(link.target_id)}}">{{ link.label }}</RouterLink><button v-for="(ref,index) in article.references" :key="index" @click="reference(ref)">{{ ref.book_slug }} {{ ref.chapter }}:{{ ref.verse_from }}–{{ ref.verse_to }}</button></template><template v-else><form @submit.prevent="submitted=query;offset=0"><input v-model="query" :aria-label="text.search"><button>{{ text.search }}</button></form><template v-for="(row,index) in rows" :key="index"><p v-if="row.variation">{{ row.variation }} → {{ row.standard_form }}</p><RouterLink v-else class="module-card" :to="{query:{...route.query,...(current.manifest.kind==='commentary'&&!book?{book:String(row.id)}:{entry:String(row.id),...(row.lexicon_code?{lexicon:String(row.lexicon_code)}:{})})}}">{{ row.topic || row.title || row.word || row.standard_form || row.id }}</RouterLink></template><p v-if="!total">{{ text.empty }}</p><nav><button :disabled="!offset" @click="offset=Math.max(0,offset-30)">{{ text.back }}</button><span>{{ offset+rows.length }}/{{ total }}</span><button :disabled="offset+rows.length>=total" @click="offset+=rows.length">{{ text.next }}</button></nav></template></template><TemporaryPassage v-if="temporary" :group="temporary" :code="temporaryCode" :service="chapterService" @close="temporary=undefined"/></MobileShell></template>
<style scoped>.pack{padding:12px;border-bottom:1px solid var(--line);display:flex;flex-wrap:wrap;gap:10px}.pack strong{width:100%}.module-card{display:block;margin:8px 0}nav{display:flex;justify-content:space-between;margin:16px 0}</style>
